#!/usr/bin/env node
/**
 * Tests for workflows/impl-review-loop.js. Zero dependencies — `node:test` on Node 18+.
 *
 *   node --test "tools/*.test.mjs"
 *
 * Two layers. The round-decision logic is a pure block between `// --- pure:begin` and `// --- pure:end`;
 * the test extracts it and calls it directly. The whole script is then run the way the runtime runs a
 * workflow (the body of an async function) with a scripted `agent`, to see the loop end in OK or STALL
 * and a resume carry on past a stall.
 *
 * Generated by Claude Code at the user's request.
 */

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const SOURCE = readFileSync(join(dirname(fileURLToPath(import.meta.url)), '..', 'workflows', 'impl-review-loop.js'), 'utf8');
const pure = SOURCE.split('// --- pure:begin')[1].split('// --- pure:end')[0];
const { decideRound, mergeReviews, inPerimeter, classify } =
  new Function(`${pure}\nreturn { decideRound, mergeReviews, inPerimeter, classify }`)();

const FILES = ['src/Orders/OrdersQuery.cs', 'src/Orders/Dto/', 'tests/**/Orders*.cs'];
const f = (id, extra = {}) => ({ id, path: 'src/Orders/OrdersQuery.cs', category: 'correctness', priority: 'P2', title: id, failure: 'x', ...extra });

test('inPerimeter: file, directory, glob, absolute path, case', () => {
  assert.ok(inPerimeter('src/Orders/OrdersQuery.cs', FILES));
  assert.ok(inPerimeter('src\\Orders\\Dto\\A.cs', FILES));
  assert.ok(inPerimeter('tests/unit/deep/OrdersTests.cs', FILES));
  assert.ok(inPerimeter('C:/repo/src/orders/ordersquery.cs', FILES));
  assert.ok(!inPerimeter('src/Orders/OrdersController.cs', FILES));
  assert.ok(!inPerimeter('src/Other/src/Orders/OrdersQuery.cs.bak', FILES));
  assert.ok(!inPerimeter('', FILES));
});

test('classify: a scope finding blocks, a defect outside is "trovato altro", P3 inside is minor', () => {
  assert.equal(classify(f('a'), FILES), 'blocking');
  assert.equal(classify(f('a', { priority: 'P3' }), FILES), 'minor');
  assert.equal(classify(f('a', { path: 'src/Other.cs' }), FILES), 'outOfScope');
  assert.equal(classify(f('a', { path: 'src/Other.cs', category: 'scope', priority: 'P3' }), FILES), 'blocking');
});

test('round 1, new P1/P2 findings only → FIX, they are tracked open', () => {
  const d = decideRound({ found: [f('F1'), f('F2', { priority: 'P1' })], files: FILES });
  assert.equal(d.action, 'FIX');
  assert.deepEqual(d.toFix, ['F1', 'F2']);
  assert.equal(d.tracked.F1.status, 'open');
});

test('round 1 with nothing blocking → DONE, the rest is recorded apart', () => {
  const d = decideRound({ found: [f('F1', { priority: 'P3' }), f('F2', { path: 'src/Other.cs' })], files: FILES });
  assert.equal(d.action, 'DONE');
  assert.deepEqual(d.minor, ['F1']);
  assert.deepEqual(d.outOfScope, ['F2']);
});

test('only NEW findings after a fix, the old ones closed → continue (FIX)', () => {
  const d = decideRound({
    tracked: { F1: { status: 'open' } }, verdicts: { F1: 'closed' }, found: [f('F2')], files: FILES,
  });
  assert.equal(d.action, 'FIX');
  assert.deepEqual(d.closed, ['F1']);
  assert.deepEqual(d.toFix, ['F2']);
});

test('the same finding still open after a fix → STALL', () => {
  const d = decideRound({ tracked: { F1: { status: 'open' } }, verdicts: { F1: 'open' }, found: [f('F2')], files: FILES });
  assert.equal(d.action, 'STALL');
  assert.deepEqual(d.stalled, [{ id: 'F1', why: 'still-open' }]);
});

test('a finding closed earlier that is open again → STALL', () => {
  const d = decideRound({ tracked: { F1: { status: 'closed' } }, verdicts: { F1: 'open' }, files: FILES });
  assert.equal(d.action, 'STALL');
  assert.deepEqual(d.stalled, [{ id: 'F1', why: 'reappeared' }]);
});

test('all closed, nothing new → DONE', () => {
  const d = decideRound({ tracked: { F1: { status: 'open' }, F2: { status: 'closed' } }, verdicts: { F1: 'closed', F2: 'closed' }, files: FILES });
  assert.equal(d.action, 'DONE');
  assert.deepEqual(d.closed, ['F1']);
});

test('an open finding the reviewer gave no verdict for is a stall, never a silent pass', () => {
  const d = decideRound({ tracked: { F1: { status: 'open' } }, verdicts: {}, files: FILES });
  assert.equal(d.action, 'STALL');
  assert.equal(d.stalled[0].why, 'no-verdict');
});

test('resolution: accept drops the stall; guidance sends the stalled finding back to the fixer', () => {
  const base = { tracked: { F1: { status: 'open' } }, verdicts: { F1: 'open' }, files: FILES };
  const accepted = decideRound({ ...base, resolution: { accept: ['F1'] } });
  assert.equal(accepted.action, 'DONE');
  assert.equal(accepted.tracked.F1.status, 'accepted');
  const guided = decideRound({ ...base, resolution: { guidance: 'use a join' } });
  assert.equal(guided.action, 'FIX');
  assert.deepEqual(guided.toFix, ['F1']);
});

test('mergeReviews: open wins over closed, duplicates collapse, a scope finding survives', () => {
  const m = mergeReviews([
    { previous: [{ id: 'F1', status: 'closed' }], found: [{ path: 'a.cs', line: 3, category: 'correctness' }] },
    { previous: [{ id: 'F1', status: 'open' }], found: [{ path: 'A.cs', line: 3, category: 'correctness' }, { path: 'b.cs', category: 'scope' }] },
  ]);
  assert.equal(m.verdicts.F1, 'open');
  assert.equal(m.found.length, 2);
});

// ── the whole script, with a scripted agent ──────────────────────────────────────────────────────────
const AsyncFunction = (async () => {}).constructor;
const BODY = SOURCE.replace(/^export /, '');

/** Runs the workflow; `reviews` is the queue of review answers (one per reviewer call), fixes always succeed. */
async function run(args, reviews) {
  const calls = [];
  const queue = [...reviews];
  const agent = async (prompt, opts = {}) => {
    calls.push({ prompt, opts });
    if (opts.agentType === 'implementer') return { scope: 's', files: ['src/Orders/OrdersQuery.cs'], evidence: 'ok', openQuestions: [] };
    return queue.shift();
  };
  const parallel = (thunks) => Promise.all(thunks.map((t) => t()));
  const fn = new AsyncFunction('args', 'agent', 'parallel', 'pipeline', 'phase', 'log', 'budget', 'workflow', BODY);
  const out = await fn(args, agent, parallel, null, () => {}, () => {}, {}, null);
  return { out, calls };
}

const ARGS = { brief: 'fix it', perimeter: { files: FILES }, size: 'M' };
const review = (previous, found = []) => ({ previous, found, checked: 'read' });
const finding = (extra = {}) => ({ title: 't', path: 'src/Orders/OrdersQuery.cs', category: 'correctness', priority: 'P2', failure: 'x', ...extra });

test('script: new findings, fix, then all closed → OK in 2 rounds, out-of-scope finding listed', async () => {
  const { out, calls } = await run(ARGS, [
    review([], [finding(), finding({ path: 'src/Other.cs' })]),
    review([{ id: 'F1', status: 'closed' }]),
  ]);
  assert.equal(out.status, 'OK');
  assert.equal(out.rounds, 2);
  assert.equal(out.outOfScope.length, 1);
  assert.equal(out.outOfScope[0].id, 'F2');
  assert.deepEqual(calls.filter((c) => c.opts.agentType === 'implementer').map((c) => c.opts.label), ['implement', 'fix R1']);
});

test('script: the same finding still open after the fix → STALL, then a resume with guidance goes on to OK', async () => {
  const stalled = await run(ARGS, [review([], [finding()]), review([{ id: 'F1', status: 'open' }])]);
  assert.equal(stalled.out.status, 'STALL');
  assert.equal(stalled.out.stall.round, 2);
  assert.equal(stalled.out.stall.findings[0].id, 'F1');
  assert.equal(stalled.out.open.length, 1);

  const resumed = await run({ ...ARGS, resolutions: [{ round: 2, guidance: 'use a join' }] }, [
    review([], [finding()]), review([{ id: 'F1', status: 'open' }]), review([{ id: 'F1', status: 'closed' }]),
  ]);
  assert.equal(resumed.out.status, 'OK');
  assert.equal(resumed.out.rounds, 3);
  assert.match(resumed.calls.filter((c) => c.opts.label === 'fix R2')[0].prompt, /use a join/);
});

test('script: a closed finding that reappears → STALL', async () => {
  const { out } = await run(ARGS, [
    review([], [finding()]),
    review([{ id: 'F1', status: 'closed' }], [finding({ path: 'src/Orders/Dto/A.cs' })]),
    review([{ id: 'F1', status: 'open' }, { id: 'F2', status: 'closed' }]),
  ]);
  assert.equal(out.status, 'STALL');
  assert.equal(out.stall.findings[0].why, 'reappeared');
});

test('script: reviewers by size, effort and model', async () => {
  const sizes = {};
  for (const size of ['S', 'M', 'L']) {
    const { calls } = await run({ ...ARGS, size, touches: ['security', 'performance'] }, size === 'L' ? [review([]), review([]), review([]), review([])] : [review([])]);
    sizes[size] = calls.filter((c) => c.opts.label?.startsWith('R1')).map((c) => `${c.opts.agentType}:${c.opts.model}:${c.opts.effort}`);
  }
  assert.deepEqual(sizes.S, ['code-reviewer:sonnet:medium']);
  assert.deepEqual(sizes.M, ['code-reviewer:sonnet:high']);
  assert.deepEqual(sizes.L, ['code-reviewer:sonnet:high', 'code-reviewer:opus:high', 'review-security:sonnet:high', 'review-performance:sonnet:high']);
});

test('script: the implementer runs at medium unless the brief asks for high', async () => {
  assert.equal((await run(ARGS, [review([])])).calls[0].opts.effort, 'medium');
  assert.equal((await run({ ...ARGS, implementerEffort: 'high' }, [review([])])).calls[0].opts.effort, 'high');
});

test('script: no brief or no perimeter is refused without spawning', async () => {
  const { out, calls } = await run({ brief: 'x' }, []);
  assert.match(out, /args\.perimeter\.files are required/);
  assert.equal(calls.length, 0);
});
